What do you think about using a new class instead of `ConfigureNamedOption` which doesn't need to hold to the dependency and creates it when `Configure` is called?

```csharp
internal class LazyConfigureNamedOptions<TOptions, TDep> : IConfigureNamedOptions<TOptions>, IConfigureOptions<TOptions>
        where TOptions : class
        where TDep : class
    {
        private readonly string _name;
        private readonly IServiceProvider _serviceProvider;
        private readonly Action<TOptions, TDep> _action;


        public LazyConfigureNamedOptions(string name, IServiceProvider serviceProvider, Action<TOptions, TDep> action)
        {
            _name = name;
            _serviceProvider = serviceProvider;
            _action = action;
        }

        public virtual void Configure(string name, TOptions options)
        {
            if (options == null)
            {
                throw new ArgumentNullException(nameof(options));
            }

            // Null name is used to configure all named options.
            if (_name == null || name == _name)
            {
                _action?.Invoke(options, _serviceProvider.GetService<TDep>());
            }
        }

        public void Configure(TOptions options) => Configure(Options.DefaultName, options);
    }
```
